def main() -> int:
    if OUTPUT.exists():
        raise SystemExit(f"refusing to overwrite Reviewer A return: {OUTPUT}")
    packets = [json.loads(line) for line in PACKET.read_text(encoding="utf-8").splitlines() if line]
    tokens = {row["family_token"] for row in packets}
    if tokens != set(DECISIONS) or len(packets) != 25:
        raise SystemExit("packet/decision token mismatch")
    returns = []
    for row in packets:
        decision, envelope, contrast, rationale = DECISIONS[row["family_token"]]
        member_tokens = {member["member_token"] for member in row["members"]}
        if member_tokens != {"S-1", "S-2", "S-3"} or set(contrast) != member_tokens:
            raise SystemExit(f"member evidence mismatch: {row['family_token']}")
        returns.append({"record_type":"source_native_full_source_family_review_return", "family_token":row["family_token"], "decision":decision, "common_envelope_evidence":envelope, "member_contrast_evidence":contrast, "rationale":rationale})
    OUTPUT.write_text("".join(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n" for row in returns), encoding="utf-8")
    print(json.dumps({"return_sha256":hashlib.sha256(OUTPUT.read_bytes()).hexdigest(), "families":len(returns), "decisions":{d:sum(row["decision"]==d for row in returns) for d in sorted({row["decision"] for row in returns})}}, indent=2))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
